#include <vector>
#include <queue>
#include <algorithm>
#include <map>

class Solution {
public:
    std::vector<std::vector<int>> multiSourceFloodFill(int n, int m, std::vector<std::vector<int>>& sources) {
        std::vector<std::vector<int>> grid(n, std::vector<int>(m, 0));
        std::vector<std::vector<int>> dist(n, std::vector<int>(m, 1e9));
        std::map<std::pair<int, int>, int> cellSources;
        for (const auto& s : sources) {
            std::pair<int, int> cell = {s[0], s[1]};
            if (!cellSources.count(cell) || s[2] > cellSources[cell]) {
                cellSources[cell] = s[2];
            }
        }
        std::queue<std::pair<int, int>> q;
        for (const auto& [cell, col] : cellSources) {
            grid[cell.first][cell.second] = col;
            dist[cell.first][cell.second] = 0;
            q.push(cell);
        }
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int curDist = 0;
        while (!q.empty()) {
            int sz = q.size();
            std::map<std::pair<int, int>, int> nextColors;
            for (int i = 0; i < sz; ++i) {
                auto [r, c] = q.front();
                q.pop();
                int col = grid[r][c];
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dirs[d][0], nc = c + dirs[d][1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                        if (dist[nr][nc] > curDist + 1) {
                            std::pair<int, int> ncell = {nr, nc};
                            if (!nextColors.count(ncell) || col > nextColors[ncell]) {
                                nextColors[ncell] = col;
                            }
                        }
                    }
                }
            }
            curDist++;
            for (const auto& [cell, col] : nextColors) {
                if (dist[cell.first][cell.second] == 1e9) {
                    dist[cell.first][cell.second] = curDist;
                    grid[cell.first][cell.second] = col;
                    q.push(cell);
                }
            }
        }
        return grid;
    }
};

import java.util.*;

class Solution {
    public int[][] multiSourceFloodFill(int n, int m, int[][] sources) {
        int[][] grid = new int[n][m];
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        Map<Long, Integer> cellSources = new HashMap<>();
        for (int[] s : sources) {
            long key = ((long)s[0] << 32) | (s[1] & 0xFFFFFFFFL);
            cellSources.put(key, Math.max(cellSources.getOrDefault(key, 0), s[2]));
        }
        Queue<int[]> q = new LinkedList<>();
        for (Map.Entry<Long, Integer> entry : cellSources.entrySet()) {
            int r = (int)(entry.getKey() >> 32);
            int c = (int)(long)entry.getKey();
            int col = entry.getValue();
            grid[r][c] = col;
            dist[r][c] = 0;
            q.offer(new int[]{r, c});
        }
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int curDist = 0;
        while (!q.isEmpty()) {
            int sz = q.size();
            Map<Long, Integer> nextColors = new HashMap<>();
            for (int i = 0; i < sz; i++) {
                int[] cell = q.poll();
                int r = cell[0], c = cell[1];
                int col = grid[r][c];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                        if (dist[nr][nc] > curDist + 1) {
                            long nKey = ((long)nr << 32) | (nc & 0xFFFFFFFFL);
                            nextColors.put(nKey, Math.max(nextColors.getOrDefault(nKey, 0), col));
                        }
                    }
                }
            }
            curDist++;
            for (Map.Entry<Long, Integer> entry : nextColors.entrySet()) {
                int nr = (int)(entry.getKey() >> 32);
                int nc = (int)(long)entry.getKey();
                if (dist[nr][nc] == Integer.MAX_VALUE) {
                    dist[nr][nc] = curDist;
                    grid[nr][nc] = entry.getValue();
                    q.offer(new int[]{nr, nc});
                }
            }
        }
        return grid;
    }
}

function multiSourceFloodFill(n, m, sources) {
    const grid = Array.from({ length: n }, () => new Array(m).fill(0));
    const dist = Array.from({ length: n }, () => new Array(m).fill(Infinity));
    const cellSources = new Map();
    for (const [r, c, col] of sources) {
        const key = `${r},${c}`;
        cellSources.set(key, Math.max(cellSources.get(key) || 0, col));
    }
    const q = [];
    for (const [key, col] of cellSources.entries()) {
        const [r, c] = key.split(',').map(Number);
        grid[r][c] = col;
        dist[r][c] = 0;
        q.push([r, c]);
    }
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let curDist = 0;
    let head = 0;
    while (head < q.length) {
        const sz = q.length - head;
        const nextColors = new Map();
        for (let i = 0; i < sz; i++) {
            const [r, c] = q[head++];
            const col = grid[r][c];
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    if (dist[nr][nc] > curDist + 1) {
                        const nKey = `${nr},${nc}`;
                        nextColors.set(nKey, Math.max(nextColors.get(nKey) || 0, col));
                    }
                }
            }
        }
        curDist++;
        for (const [nKey, col] of nextColors.entries()) {
            const [nr, nc] = nKey.split(',').map(Number);
            if (dist[nr][nc] === Infinity) {
                dist[nr][nc] = curDist;
                grid[nr][nc] = col;
                q.push([nr, nc]);
            }
        }
    }
    return grid;
}
